package httpserver

import "strings"

// localizedServiceTopicCopy provides a complete, conservative localized shell
// for the fixed service pages. The English source remains the long-form
// editorial version; each other market receives native headings, workflow
// labels, FAQs, and SEO text instead of an English fallback.
func localizedServiceTopicCopy(base publicServiceTopicCopy, locale string) publicServiceTopicCopy {
	code := strings.ToLower(strings.Split(strings.TrimSpace(locale), "-")[0])
	if code == "en" {
		return base
	}
	name := localizedTopicNames[code][base.Slug]
	if name == "" {
		return base
	}
	d := localizedTopicDescriptors[code][base.Slug]
	if d == "" {
		d = name
	}
	base.NavLabel = name
	base.ShortDescription = d
	base.SEOTitle = localizedTopicSEOTitles[code][base.Slug]
	base.SEODescription = localizedTopicSEODescriptions[code][base.Slug]
	base.SEOKeywords = localizedTopicKeywords[code][base.Slug]
	base.SEOKeywordsText = strings.Join(base.SEOKeywords, ", ")
	base.HeroKicker = strings.ToUpper(name) + " / CHINA"
	base.HeroTitle = localizedTopicTitles[code][base.Slug]
	base.HeroBody = localizedTopicBodies[code][base.Slug]
	base.HeroPrimary = localizedUI[code].primary
	base.HeroSecondary = localizedUI[code].secondary
	base.HeroVisualLabel = localizedUI[code].benefitLabels[0]
	base.HeroVisualTitle = localizedUI[code].benefitTitles[0]
	base.HeroVisualBody = localizedUI[code].benefitBodies[0]
	base.HeroStages = []string{localizedUI[code].workflowSteps[0], localizedUI[code].workflowSteps[1], localizedUI[code].workflowSteps[2], localizedUI[code].workflowSteps[3]}
	base.IntroTitle = localizedUI[code].introTitle + " " + name + "."
	base.Intro = []string{
		localizedUI[code].introBody1 + " " + strings.ToLower(d) + ".",
		localizedUI[code].introBody2,
	}
	base.SituationsTitle = localizedUI[code].situationsTitle
	base.SituationsLead = localizedUI[code].situationsLead
	base.Situations = []publicServiceTopicSituation{
		{Label: localizedUI[code].situationLabels[0], Title: localizedUI[code].situationTitles[0], Body: localizedUI[code].situationBodies[0] + " " + d + "."},
		{Label: localizedUI[code].situationLabels[1], Title: localizedUI[code].situationTitles[1], Body: localizedUI[code].situationBodies[1]},
		{Label: localizedUI[code].situationLabels[2], Title: localizedUI[code].situationTitles[2], Body: localizedUI[code].situationBodies[2]},
	}
	base.WorkflowTitle = localizedUI[code].workflowTitle
	base.WorkflowLead = localizedUI[code].workflowLead
	base.Workflow = localizedWorkflow(code, d)
	base.ScopeTitle = localizedUI[code].scopeTitle
	base.ScopeLead = localizedUI[code].scopeLead
	base.Included = localizedScopes(code, true)
	base.Confirm = localizedScopes(code, false)
	base.NeedsTitle = localizedUI[code].needsTitle
	base.NeedsLead = localizedUI[code].needsLead
	base.Needs = append([]string(nil), localizedUI[code].needs...)
	base.BenefitsTitle = localizedUI[code].benefitsTitle
	base.BenefitsLead = localizedUI[code].benefitsLead
	base.Benefits = localizedBenefits(code)
	base.FAQs = localizedFAQs(code, name)
	base.CTATitle = localizedUI[code].ctaTitle
	base.CTABody = localizedUI[code].ctaBody + " " + name + "."
	base.CTAButton = localizedUI[code].primary
	base.Related = localizedRelated(code)
	return base
}

func localizedWorkflow(code, descriptor string) []publicServiceTopicStep {
	u := localizedUI[code]
	steps := make([]publicServiceTopicStep, 0, 6)
	for i, title := range u.workflowSteps {
		body := u.workflowBodies[i]
		if i == 0 {
			body += " " + descriptor + "."
		}
		steps = append(steps, publicServiceTopicStep{Marker: workflowMarkers(code)[i], Title: title, Body: body})
	}
	return steps
}

func workflowMarkers(code string) []string {
	if code == "it" {
		return []string{"I", "II", "III", "IV", "V", "VI"}
	}
	return []string{"01", "02", "03", "04", "05", "06"}
}

func localizedScopes(code string, included bool) []publicServiceTopicScope {
	u := localizedUI[code]
	if included {
		return []publicServiceTopicScope{{Title: u.included[0], Body: u.includedBodies[0]}, {Title: u.included[1], Body: u.includedBodies[1]}, {Title: u.included[2], Body: u.includedBodies[2]}}
	}
	return []publicServiceTopicScope{{Title: u.confirm[0], Body: u.confirmBodies[0]}, {Title: u.confirm[1], Body: u.confirmBodies[1]}, {Title: u.confirm[2], Body: u.confirmBodies[2]}}
}

func localizedBenefits(code string) []publicServiceTopicBenefit {
	u := localizedUI[code]
	return []publicServiceTopicBenefit{{Label: u.benefitLabels[0], Title: u.benefitTitles[0], Body: u.benefitBodies[0]}, {Label: u.benefitLabels[1], Title: u.benefitTitles[1], Body: u.benefitBodies[1]}, {Label: u.benefitLabels[2], Title: u.benefitTitles[2], Body: u.benefitBodies[2]}, {Label: u.benefitLabels[3], Title: u.benefitTitles[3], Body: u.benefitBodies[3]}}
}

func localizedFAQs(code, name string) []publicFAQItem {
	u := localizedUI[code]
	return []publicFAQItem{{Question: u.faqQuestions[0], Answer: u.faqAnswers[0] + " " + name + "."}, {Question: u.faqQuestions[1], Answer: u.faqAnswers[1]}, {Question: u.faqQuestions[2], Answer: u.faqAnswers[2]}, {Question: u.faqQuestions[3], Answer: u.faqAnswers[3]}}
}

func localizedRelated(code string) []publicServiceTopicRelated {
	u := localizedUI[code]
	return []publicServiceTopicRelated{{Title: u.related[0], Body: u.relatedBodies[0], URL: "/product-sourcing"}, {Title: u.related[1], Body: u.relatedBodies[1], URL: "/services/inventory-storage"}, {Title: u.related[2], Body: u.relatedBodies[2], URL: "/services/worldwide-fulfillment"}}
}

type localizedTopicUI struct {
	primary, secondary, introTitle, introBody1, introBody2 string
	situationsTitle, situationsLead                        string
	situationLabels, situationTitles, situationBodies      []string
	workflowTitle, workflowLead                            string
	workflowSteps, workflowBodies                          []string
	scopeTitle, scopeLead                                  string
	included, includedBodies, confirm, confirmBodies       []string
	needsTitle, needsLead                                  string
	needs                                                  []string
	benefitsTitle, benefitsLead                            string
	benefitLabels, benefitTitles, benefitBodies            []string
	faqQuestions, faqAnswers                               []string
	ctaTitle, ctaBody                                      string
	related, relatedBodies                                 []string
}

